const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\r?\n/);
if (data.length === 0) process.exit(0);

const N = data[0].trim();
const M = parseInt(data[1], 10);

const groups = ['abc', 'def', 'ghi', 'jkl', 'mno', 'pqrs', 'tuv', 'wxyz'];
const map = new Array(26);

for (let d = 2; d <= 9; d++) {
  const digit = String(d);
  for (const ch of groups[d - 2]) {
    map[ch.charCodeAt(0) - 97] = digit;
  }
}

let answer = 0;

for (let i = 0; i < M; i++) {
  const s = data[2 + i].trim();

  if (s.length !== N.length) continue;

  let ok = true;

  for (let j = 0; j < s.length; j++) {
    const digit = map[s.charCodeAt(j) - 97];
    if (digit !== N[j]) {
      ok = false;
      break;
    }
  }

  if (ok) answer++;
}

console.log(answer);
